#include <queue>
#include <vector>
#include <functional>
#include <iostream>

// Default: Max-Heap (uses std::less)
std::priority_queue<int> max_q;
max_q.push(5); max_q.push(1);
std::cout << "Max: " << max_q.top() << "\n"; // Output: 5

// Custom: Min-Heap (uses std::greater)
std::priority_queue<int, 
                    std::vector<int>, 
                    std::greater<int>> min_q;
min_q.push(5); min_q.push(1);
std::cout << "Min: " << min_q.top() << "\n"; // Output: 1
